mapper.select:
SELECT 
FROM pmis_flow_delegate_auth
WHERE tenant_id = #{tenantId}
  AND owner_user_id = #{ownerUserId}
  AND deleted = 0

      AND auth_status = #{status}

ORDER BY created_at DESC

SELECT 
FROM pmis_flow_delegate_auth
WHERE tenant_id = #{tenantId}
  AND delegate_user_id = #{delegateUserId}
  AND deleted = 0

      AND auth_status = #{status}

ORDER BY created_at DESC

mapper.update:
UPDATE pmis_flow_delegate_auth
SET auth_status = 'EXPIRED',
    updated_at = #{updatedAt}
WHERE deleted = 0
  AND auth_status = 'ENABLED'
  AND end_time < #{now}

UPDATE pmis_flow_delegate_auth
SET auth_status = #{status},
    updated_at = #{updatedAt}
WHERE id = #{id}
  AND deleted = 0
